const taken=sid=>{const t=new Set();for(let r=0;r<6;r++)for(let c=1;c<=8;c++){const k='ABCDEF'[r]+c;if(parseInt(h(sid+k).slice(-4),16)/65535<.2)t.add(k)}DB().b.filter(b=>b.sid==sid&&b.status=='CONFIRMED').forEach(b=>b.seats.split(',').forEach(s=>t.add(s)));return t};
function register(name,email,pw){const d=DB();if(!name.trim()||!/^[\w.+-]+@[\w.-]+$/.test(email)||pw.length<6)throw Error('Enter your name, a valid email and a password of at least 6 characters.');if(d.u.some(u=>u.email==email.toLowerCase()))throw Error('An account with this email already exists. Sign in instead.');const u={id:d.u.length+1,name:name.trim(),email:email.toLowerCase(),pw:h(pw)};d.u.push(u);save(d);return u}
function login(email,pw){const u=DB().u.find(x=>x.email==email.toLowerCase());if(!u||u.pw!==h(pw))throw Error('Email or password is incorrect.');return u}
function bookSeats(uid,sid,seats,pay,code){const d=DB();if(!d.u.some(u=>u.id==uid))throw Error('Sign in to book.');const s=show(sid);if(!s)throw Error('Show not found.');
 if(!seats.length||seats.length>8)throw Error('Choose between 1 and 8 seats.');if(seats.some(k=>!/^[A-F][1-8]$/.test(k)))throw Error('Invalid seat selected.');
 if(pay=='FAIL')throw Error('Demo payment declined. No booking was made. Choose another payment method.');
 const t=taken(sid);if(seats.some(k=>t.has(k)))throw Error('Some seats were just taken. Go back and pick different seats.');
 const tot=seats.reduce((a,k)=>a+sp(s,k),0),dc=disc(code,tot);const b={id:d.b.length+1,uid,sid,seats:seats.join(','),amount:tot-dc+FEE*seats.length,coupon:dc?code.toUpperCase():'',status:'CONFIRMED',ref:'DEMO-'+Math.random().toString(16).slice(2,10).toUpperCase()};d.b.push(b);save(d);return b.id}

