function exportCsv(){const r=[['Booking','Movie','Theatre','Date','Time','Seats','Amount','Status']];DB().b.filter(x=>x.uid==user.id).forEach(x=>{const s=show(x.sid);r.push(['CB'+x.id,M[s.mid-1].title,s.theatre,s.date,s.time,x.seats.replace(/,/g,' '),x.amount,x.status])});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([r.map(l=>l.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\n')],{type:'text/csv'}));a.download='cinebook-bookings.csv';a.click();toast('CSV downloaded')}
