const KB=[[/cancel|refund/,'Open My bookings and choose Cancel on a confirmed booking. A demo refund is marked as started.'],[/pay|upi|card|money|fail/,'Payments are simulated and no money is charged. You can test a failed payment at checkout.'],[/seat|hold|timer|premium|executive|classic/,'Seats are held for 5 minutes at checkout. Rows A-B are Premium, C-D Executive and E-F Classic.'],[/coupon|offer|discount|code/,'Try CINE10, FIRST100 or FAMILY20 (needs ₹1,000 or more). See the Offers page.'],[/ticket|qr|print|calendar/,'Open My bookings and choose Ticket. You can print it, add it to your calendar or copy the details.'],[/theatre|theater|cinema|show/,'We list 8 theatres. Open a movie to compare showtimes, or see the Theatres page.'],[/login|sign|password|account/,'Use Sign in at the top. Demo account: demo@cinebook.com with password demo123.']];
(function(){const d=document.createElement('div');d.id='chat';d.innerHTML=`<div id="cp" hidden><div class="ch"><span>CinéBot <small id="cm"></small></span><button id="cx" aria-label="Close chat">×</button></div><div id="cl"></div><div class="cq">${['Recommend a movie','Cancel booking','Seat tiers','Coupons'].map(x=>`<button class="chip">${x}</button>`).join('')}</div><form id="cf"><input class="in" id="ci" placeholder="Ask CinéBot anything" aria-label="Chat message" autocomplete="off"><button class="btn">Send</button></form></div><button id="cb" class="btn red" aria-label="Open chat">Ask CinéBot</button>`;document.body.append(d);
 const hist=[];let ai=location.protocol!='file:';const badge=()=>$('#cm').textContent=ai?'AI':'Basic mode';badge();
 const link=t=>esc(t).replace(new RegExp(M.map(m=>m.title).sort((a,b)=>b.length-a.length).join('|'),'g'),x=>`<a href="#/movie/${M.find(m=>m.title==x).id}">${x}</a>`);
 const say=(t,me)=>{const m=document.createElement('div');m.className='msg '+(me?'me':'bot');m[me?'textContent':'innerHTML']=me?t:link(t);$('#cl').append(m);$('#cl').scrollTop=1e9;return m};
 const ctx=()=>`[Site data. Movies: ${M.map(m=>`${m.title} (${m.genre}, ${m.lang}, ${m.rating})`).join('; ')}. Signed-in user: ${user?user.name:'none'}. Today: ${fmt(dateOf(0))}.] `;
 const ask=async q=>{say(q,1);hist.push({role:'user',content:q});const t=say('…');let r='';
  if(ai){try{const m=hist.slice(-9).map((x,i,a)=>i==a.length-1?{...x,content:ctx()+x.content}:x),x=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:m})});if(x.ok)r=(await x.json()).reply;else{ai=false;badge();say(x.status==503?'AI is switched off because no API key was found. Start the Java server with your key to turn it on. I will use basic answers for now.':'The AI service could not be reached. I will use basic answers for now.')}}catch(e){ai=false;badge()}}
  if(!r){const k=KB.find(z=>z[0].test(q.toLowerCase()));r=k?k[1]:'I am not sure about that. Raise a ticket on the Support page and the team will follow up.'}
  hist.push({role:'assistant',content:r});t.innerHTML=link(r);$('#cl').scrollTop=1e9};
 say(ai?"Hi, I'm CinéBot, powered by AI. Ask me to recommend a movie or help with booking, seats, coupons or tickets.":"Hi, I'm CinéBot in basic mode. Open the site through the Java server with an API key to unlock AI answers.");
 $('#cb').onclick=()=>{$('#cp').hidden=!$('#cp').hidden;$('#ci').focus()};$('#cx').onclick=()=>$('#cp').hidden=true;
 $('#cf').onsubmit=e=>{e.preventDefault();const v=$('#ci').value.trim();if(v){$('#ci').value='';ask(v)}};document.querySelectorAll('.cq .chip').forEach(c=>c.onclick=()=>ask(c.textContent))})();
addEventListener('keydown',e=>{if(e.key=='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){const q=$('#q');if(q){e.preventDefault();q.focus()}}});
const row=(t,l,id)=>l.length?`<section class="wrap rowsec"><div class="rh"><h2>${t}</h2><span><button class="arr" onclick="scr('${id}',-1)" aria-label="Scroll left">‹</button><button class="arr" onclick="scr('${id}',1)" aria-label="Scroll right">›</button></span></div><div class="strip" id="${id}">${l.map(card).join('')}</div></section>`:'';
const scr=(id,d)=>document.getElementById(id).scrollBy({left:d*620,behavior:'smooth'});
const RV=()=>JSON.parse(localStorage.getItem('cbr3')||'{}');
function reviews(m){const l=RV()[m.id]||[],avg=l.length?(l.reduce((a,x)=>a+x.s,0)/l.length).toFixed(1):null;
 $('#rv').innerHTML=`<h2>Reviews</h2><p class="sub">${avg?`★ ${avg} from ${l.length} review${l.length>1?'s':''} on CinéBook`:'No reviews yet. Watched it? Be the first to rate.'}</p><form id="rf" class="box" style="margin:0 0 24px;max-width:560px"><label for="rs">Your rating</label><select class="in" id="rs">${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)} (${n}/5)</option>`).join('')}</select><label for="rt">Your review</label><textarea class="in" id="rt" rows="3" maxlength="300" required></textarea><button class="btn" style="margin-top:14px">Post review</button></form>${l.slice().reverse().map(x=>`<div class="bk"><div><b>${esc(x.n)}</b> · ${'★'.repeat(x.s)}<br><small>${esc(x.t)}</small></div></div>`).join('')}`;
 $('#rf').onsubmit=e=>{e.preventDefault();if(!user){next='#/movie/'+m.id;go('#/signin');toast('Sign in to post a review');return}const a=RV();(a[m.id]=a[m.id]||[]).push({n:user.name,s:+$('#rs').value,t:$('#rt').value.trim()});localStorage.setItem('cbr3',JSON.stringify(a));reviews(m);toast('Review posted')}}
function gsearch(i){const m=M.find(x=>x.title.toLowerCase()==i.value.toLowerCase());if(m)go('#/movie/'+m.id);else{Q=i.value;if(location.hash&&location.hash!='#/')go('#/');else route();setTimeout(()=>$('#movies')&&$('#movies').scrollIntoView(),60)}i.value=''}
const PG=[['Home','#/'],['Theatres','#/theatres'],['Offers','#/offers'],['Support','#/support'],['My bookings','#/bookings'],['Profile','#/profile'],['My insights','#/insights'],['How we work','#/agile'],['Help centre','#/help']];
function palette(){if($('#pal'))return;const d=document.createElement('div');d.id='pal';d.innerHTML=`<div class="pbox" role="dialog" aria-label="Quick search"><input id="pi" placeholder="Search movies or jump to a page…" autocomplete="off" aria-label="Quick search"><div id="pl"></div><small class="ph">Enter to open · Esc to close · Ctrl+K anywhere</small></div>`;document.body.append(d);
 const render=()=>{const q=$('#pi').value.toLowerCase(),r=[...PG.map(p=>({t:p[0],s:'Page',h:p[1]})),...M.map(m=>({t:m.title,s:m.genre+' · '+m.lang,h:'#/movie/'+m.id}))].filter(x=>x.t.toLowerCase().includes(q)).slice(0,8);$('#pl').innerHTML=r.map((x,i)=>`<a href="${x.h}" class="${i?'':'on'}"><b>${x.t}</b><small>${x.s}</small></a>`).join('')||'<small>No matches</small>'};
 d.onclick=e=>{if(e.target==d||e.target.closest('a'))d.remove()};$('#pi').oninput=render;$('#pi').onkeydown=e=>{if(e.key=='Escape')d.remove();if(e.key=='Enter'){const a=$('#pl a');if(a){location.hash=a.getAttribute('href');d.remove()}}};render();$('#pi').focus()}
addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()=='k'){e.preventDefault();palette()}});
function voice(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return toast('Voice search needs Chrome or Edge.');const r=new R();r.lang='en-IN';r.onstart=()=>toast('Listening… say a movie name');r.onresult=e=>{const t=e.results[0][0].transcript.replace(/\.$/,'');toast('Heard: '+t);gsearch({value:t})};r.onerror=()=>toast('Could not hear you. Please try again.');r.start()}
const best=(t,n)=>{for(const r of 'CDBEAF'){const c=[1,2,3,4,5,6,7,8].filter(c=>c+n-1<=8).map(c=>({c,ok:[...Array(n)].every((_,i)=>!t.has(r+(c+i))),d:Math.abs(c+(n-1)/2-4.5)})).filter(x=>x.ok).sort((a,b)=>a.d-b.d)[0];if(c)return[...Array(n)].map((_,i)=>r+(c.c+i))}return null};
function ticketPng(id){const b=DB().b.find(x=>x.id==id),s=show(b.sid),m=M[s.mid-1],t=(x,y,sz,c,w)=>`<text x='36' y='${y}' font-family='Arial' font-size='${sz}' font-weight='${w||'normal'}' fill='${c}'>${esc(x)}</text>`;
 const svg=`<svg xmlns='http://www.w3.org/2000/svg' width='900' height='360'><rect width='900' height='360' rx='24' fill='#fff4dc'/><rect width='900' height='70' rx='24' fill='#e5234b'/><rect y='40' width='900' height='30' fill='#e5234b'/>${t('CINEBOOK TICKET',48,30,'#fff4dc','bold')}${t(m.title,130,42,'#1b1400','bold')}${t(s.theatre+' · '+s.screen,185,24,'#1b1400')}${t(s.date+' · '+s.time,225,24,'#1b1400')}${t('Seats: '+b.seats.replace(/,/g,', '),275,30,'#e5234b','bold')}${t('Booking #CB'+b.id+' · '+b.ref,325,20,'#1b1400')}<g transform='translate(690,110) scale(8)'>${qr(b.ref).replace(/^<svg[^>]*>/,'').replace('</svg>','')}</g></svg>`;
 const i=new Image();i.onload=()=>{const c=document.createElement('canvas');c.width=900;c.height=360;c.getContext('2d').drawImage(i,0,0);c.toBlob(bl=>{const a=document.createElement('a');a.href=URL.createObjectURL(bl);a.download='cinebook-ticket-'+b.id+'.png';a.click();toast('Ticket image saved')})};i.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}
function shareTk(id){const b=DB().b.find(x=>x.id==id),s=show(b.sid),t=`I'm watching ${M[s.mid-1].title} at ${s.theatre}, ${s.date} ${s.time}. Seats ${b.seats}. Join me!`;if(navigator.share)navigator.share({title:'CinéBook',text:t}).catch(()=>{});else{navigator.clipboard&&navigator.clipboard.writeText(t);toast('Invite copied. Paste it to your friends.')}}
function route(){const[,p,a]=(location.hash||'#/').split('/');if(p!='book'&&p!='checkout')sel.clear();if(p!='checkout')cp='';clearInterval(tm);clearInterval(ht);scrollTo(0,0);nav();({'':home,movie,book,checkout,ticket,bookings,signin,offers,theatres,profile,help,support,agile,insights}[p]||home)(a)}
addEventListener('hashchange',route);route();loadPosters();if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});
